INSERT INTO `extension_activity_designs` (`id`, `tenant_id`, `campus_id`, `extension_proposal_id`, `extension_plan_id`, `dts_record_id`, `design_code`, `tracking_number`, `title`, `banner_program`, `academic_program_id`, `unit_id`, `collaborating_agencies`, `target_beneficiaries`, `target_beneficiaries_count`, `duration_text`, `start_date`, `end_date`, `project_location`, `project_leader_user_id`, `project_leader_employee_id`, `project_leader_name`, `project_leader_title`, `context_rationale`, `general_objective`, `specific_objectives`, `program_matrix`, `budget_total`, `budget_snsu_share`, `budget_partner_share`, `budget_total_display`, `status`, `remarks`, `metadata`, `submitted_at`, `approved_at`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(1, 1, 1, 1, 1, NULL, 'SNSU-AD-2026-0001', NULL, 'Test Community Training on AI & Data Literacy', 'Digital Literacy & Information Technology Transfer', 1, 15, 'City Government of Surigao, Department of Information and Communications Technology (DICT - Caraga)', 'Barangay Officials, BHWs, and Sangguniang Kabataan of Barangay Lipata, Surigao City', 3, '2 Months (October 2026 – December 2026)', '2023-05-03', '2026-12-08', 'Barangay Lipata Gymnasium, Surigao City', 7, 7, 'Engr. Test Leader', 'Project Proponent', 'Information and Communications Technology (ICT) plays an indispensable role in community-level governance. In coastal barangays of Surigao City, manual recordkeeping continues to present bottlenecks in resident profiling, health records management, and disaster aid allocation. This project equips local officials with modern digital tools to enhance administrative transparency and service delivery.', 'To modernize frontline public service delivery and administrative recordkeeping across coastal barangays in Surigao City through digital literacy training and automated local governance systems.', '["Train 100 barangay staff and SK leaders on digital document creation and spreadsheet management.", "Establish a secure offline-capable database of residents, health indices, and clearance issuances.", "Formulate a community-led maintenance protocol to ensure continuous operation."]', '[{"id": 494, "num": 1, "is_na": false, "title": "Submission of Activity Design", "status": "pending", "remarks": "Wet-signed by Dean and Director", "file_url": null, "documents": [], "file_icon": "mdi-file-document-outline text-secondary", "file_name": null, "preview_url": null, "target_date": "February 20, 2026", "uploaded_at": null, "uploaded_by": null, "is_completed": false, "documents_count": 0, "formatted_file_size": "0 KB"}, {"id": 490, "num": 1, "is_na": false, "title": "Submission of Proposal", "status": "completed", "remarks": null, "file_url": "http://localhost:8000/storage/ext