INSERT INTO `extension_proposals` (`id`, `tenant_id`, `campus_id`, `unit_id`, `academic_program_id`, `extension_plan_id`, `dts_record_id`, `proposal_code`, `tracking_number`, `title`, `banner_program`, `banner_program_other`, `agenda_priorities`, `beneficiaries`, `target_beneficiaries_data`, `implementing_agency`, `implementing_colleges`, `lead_agency`, `collaborating_agencies`, `collaborating_agencies_data`, `duration_start`, `duration_end`, `duration_text`, `duration_months`, `project_location`, `budget_institution_share`, `fund_source_internal`, `budget_partner_share`, `fund_source_external`, `budget_total_display`, `budget_cash_amount`, `budgetary_requirements`, `project_leader_user_id`, `project_leader_employee_id`, `project_leader_name`, `project_leader_title`, `project_leader_gender`, `asst_project_leader_name`, `asst_project_leader_title`, `proponents`, `introduction`, `objectives`, `general_objective`, `specific_objectives`, `expected_outputs`, `relevance_narrative`, `sdg_alignments`, `development_gap`, `pdp_responsiveness`, `schedule_of_activities`, `risk_management`, `people_involved`, `org_structure`, `sustainability_measures`, `prepared_by_user_id`, `prepared_by_employee_id`, `prepared_by_name`, `prepared_by_designation`, `prepared_at`, `status`, `remarks`, `metadata`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(1, 1, 1, 15, 1, 1, NULL, 'SNSU-PROP-2026-0001', '202610240001', 'e-Barangay: Community ICT Literacy & Digital Public Records Automation for Coastal Barangays', 'Digital Literacy & Information Technology Transfer', NULL, '["Smart Technologies & Digital Transformation", "Community Empowerment & Governance"]', 'Barangay Officials, BHWs, and Sangguniang Kabataan of Barangay Lipata, Surigao City', '{"direct": 100, "sectors": ["Barangay Officials", "Barangay Health Workers", "Youth & SK"], "indirect": 3500}', 'Surigao del Norte State University (SNSU)', '["College of Engineering and Technology", "College of Information & Communications Technology"]', 'Surigao del Norte State University', 'City Government of Surigao, Department of Information and Communications Technology (DICT - Caraga)', '[{"name": "City Government of Surigao", "role": "Logistical support and community venue coordination"}, {"name": "DICT Caraga", "role": "Free Wi-Fi access points and technical assistance"}]', '2023-05-03', '2026-12-08', '2 Months (October 2026 – December 2026)', 2, 'Barangay Lipata Gymnasium, Surigao City', '75,000.00', '75,000.00', '20,000.00', '20,000.00', '95,000.00', 95000.00, '{"sections": {"A": {"code": "A", "items": [{"item": "Expert Resource Speaker Honoraria", "basis": "40 hrs @ 500/hr", "amount": 20000}, {"item": "Technical Facilitator Assistance", "basis": "40 hrs @ 250/hr", "amount": 10000}], "title": "Personal Services / Honoraria"}, "D": {"code": "D", "items": [{"item": "Documentation, Certificates & Transportation", "basis": "Lump sum", "amount": 10000}], "title": "Contingency & Miscellaneous"}, "B_TRAIN": {"code": "B_TRAIN", "items": [{"item": "Participant Training Kits & Workbooks", "basis": "100 sets @ 250/set", "amount": 25000}, {"item": "Training Venue Meals & Refreshments", "basis": "100 pax @ 300/pax", "amount": 30000}], "title": "Training Supplies & Materials"}}}', 7, 7, 'Antonio Jr. L. Piloton', 'Associate Professor / Project Leader', 'Male', 'Maria Elena S. Villanueva', 'Assistant Project Leader', '[{"name": "Antonio Jr. L. Piloton", "role": "Project Leader", "type": "faculty", "employee_id": 7}, {"name": "Maria Elena S. Villanueva", "role": "Assistant Project Leader", "type": "faculty", "employee_id": 8}, {"name": "Rodrigo T. Dela Cruz Jr.", "role": "Technical Facilitator", "type": "faculty", "employee_id": 9}]', 'Information and Communications Technology (ICT) plays an indispensable role in community-level governance. In coastal barangays of Surigao City, manual recordkeeping continues to present bottlenecks in resident profiling, health records management, and disaster aid allocation. This project equips local officials with modern digital tools to enhance administrative transparency and service delivery.', '[{"title": "Capacity Development", "description": "Conduct 40 hours of hands-on training on digital literacy and office automation."}, {"title": "System Deployment", "description": "Install and configure a localized electronic barangay record system."}, {"title": "Impact Assessment", "description": "Evaluate citizen satisfaction and operational turnaround time before and after implementation."}]', 'To modernize frontline public service delivery and administrative recordkeeping across coastal barangays in Surigao City through digital literacy training and automated local governance systems.', '["Train 100 barangay staff and SK leaders on digital document creation and spreadsheet management.", "Establish a secure offline-capable database of residents, health indices, and clearance issuances.", "Formulate a community-led maintenance protocol to ensure continuous operation."]', '["100 fully certified barangay personnel in digital public administration.", "1 fully operational e-Barangay Records Information System.", "1 signed Memorandum of Agreement with LGU Surigao City for sustained tech support."]', 'Directly aligns with the Philippine Development Plan (PDP) 2023-2028 Chapter on Expanding Digital Infrastructure and Enhancing Social Inclusion, alongside the Regional Development Plan of Caraga.', '{"selected": [4, 9, 11], "narrative": "Addresses SDG 4 (Quality Education) through practical digital skills training, SDG 9 (Industry, Innovation & Infrastructure) by providing IT infrastructure, and SDG 11 (Sustainable Communities) through resilient municipal e-governance."}', 'Disparity in digital literacy between urban centers and coastal frontline communities, resulting in backlogs, inaccurate resident profiles, and delays during emergency disaster response.', 'Supports Chapter 14: Promoting Inclusive and Sustainable Digital Infrastructure and Transforming Governance.', '[{"phase": "Phase I: Needs Assessment & LGU Consultation", "outputs": "Hardware readiness audit, signed MOA", "target_month": "Week 1-2"}, {"phase": "Phase II: Hands-on ICT Workshop", "outputs": "Completed modular training, skill assessment", "target_month": "Week 3-5"}, {"phase": "Phase III: System Rollout & Data Migration", "outputs": "Encoded resident database, pilot operations", "target_month": "Week 6-7"}, {"phase": "Phase IV: Monitoring & Closeout", "outputs": "Final evaluation report, user turnover", "target_month": "Week 8"}]', NULL, '{"rows": [{"id": "r1", "name": "Antonio Jr. L. Piloton", "role": "Project Leader", "responsibilities": "Overall project oversight, curriculum formulation, and institutional coordination."}, {"id": "r2", "name": "Maria Elena S. Villanueva", "role": "Assistant Project Leader", "responsibilities": "Field logistics, training materials preparation, and participant assessment."}, {"id": "r3", "name": "Rodrigo T. Dela Cruz Jr.", "role": "Technical Facilitator", "responsibilities": "Network setup, software installation, and lab support."}], "columns": [{"id": "name", "label": "Extensionist / Collaborator", "width": 35}, {"id": "role", "label": "Project Role / Title", "width": 25}, {"id": "responsibilities", "label": "Specific Responsibilities & Tasks", "width": 40}]}', '{"mode": "dynamic", "nodes": [{"id": "lead", "name": "Antonio Jr. L. Piloton", "title": "Project Leader", "parent": null}, {"id": "asst", "name": "Maria Elena S. Villanueva", "title": "Assistant Project Leader", "parent": "lead"}, {"id": "tech", "name": "Rodrigo T. Dela Cruz Jr.", "title": "Technical Lead", "parent": "asst"}]}', 'The project turnover includes a complete administrator manual, video tutorials, and a dedicated student volunteer helpdesk hosted at the SNSU College of Engineering and Technology.', 7, 7, 'Antonio Jr. L. Piloton', 'Faculty Proponent / Project Leader', '2026-10-09 13:20:33', 'approved', 'Fully approved by the University President with allocation from GAA Extension Allotment.', '{"impact_assessment": {"status": "completed", "report_url": "https://example.com/reports/impact-2026.pdf", "recorded_at": "2026-11-03 09:35:47", "conducted_at": "2026-11-03", "evaluator_name": "Dr. Impact Evaluator", "recommendations": "Schedule annual refresher workshops.", "findings_summary": "Community groups have continued independently operating the technology.", "recorded_by_user_id": 1, "sustainability_rating": "Outstanding / Highly Sustainable", "community_adoption_level": "High Adoption (Institutionalized in Community)"}, "accomplishment_report": {"updated_at": "2026-10-26T13:39:06+00:00", "date_completed": "2026-10-26", "impact_feedback": "Community Impact & Beneficiary TestimonialsCommunity Impact & Beneficiary TestimonialsCommunity Impact & Beneficiary Testimonials", "updated_by_name": "Engr. Antonio Piloton Jr.", "solutions_adopted": "Problems / Constraints EncounteredProblems / Constraints EncounteredProblems / Constraints EncounteredProblems / Constraints Encountered\\r\\nSolutions & Remedial Measures Adopted\\r\\nProblems / Constraints EncounteredProblems / Constraints EncounteredProblems / Constraints EncounteredProblems / Constraints Encountered\\r\\nSolutions & Remedial Measures Adopted\\r\\nProblems / Constraints EncounteredProblems / Constraints EncounteredProblems / Constraints EncounteredProblems / Constraints Encountered\\r\\nSolutions & Remedial Measures Adopted", "updated_by_user_id": 7, "actual_budget_spent": "95000", "problems_encountered": "Problems / Constraints EncounteredProblems / Constraints EncounteredProblems / Constraints EncounteredProblems / Constraints Encountered", "implementation_status": "Completed", "summary_accomplishments": "Summary of Key Accomplishments & MilestonesSummary of Key Accomplishments & MilestonesSummary of Key Accomplishments & MilestonesSummary of Key Accomplishments & Milestones", "actual_beneficiaries_male": "45", "actual_beneficiaries_total": "100", "actual_beneficiaries_female": "55", "actual_beneficiaries_sectors": "Specific Community Sectors / Demographics"}}', '2026-10-24 05:20:33', '2026-11-03 01:35:47', NULL),
	(2, 1, 1, 8, 7, 2, NULL, 'SNSU-PROP-2026-0002', '202610240002', 'Ligtas-Kalamidad: Structural Health Evaluation & Disaster-Resilient Evacuation Planning', 'Disaster Risk Reduction & Climate Change Adaptation', NULL, '["Climate Resilience & Environmental Protection", "Community Safety & Infrastructure"]', 'Barangay DRRM Council and Coastal Public School Teachers of Barangay Mabua', '{"direct": 60, "indirect": 2000}', 'Surigao del Norte State University (SNSU)', NULL, 'Surigao del Norte State University', 'MDRRMO Surigao City, Department of Public Works and Highways (DPWH)', NULL, '2023-05-03', '2026-12-18', '2 Months', 2, 'Barangay Mabua, Surigao City', '90,000.00', '90,000.00', '25,000.00', '25,000.00', '115,000.00', 115000.00, NULL, 12, 8, 'Maria Elena S. Villanueva', 'Assistant Professor / Project Leader', 'Female', NULL, 'Assistant Project Leader', '[{"name": "Maria Elena S. Villanueva", "role": "Project Leader", "type": "faculty", "employee_id": 8}, {"name": "Antonio Jr. L. Piloton", "role": "Co-Proponent", "type": "faculty", "employee_id": 7}]', 'Coastal public infrastructure in Northern Mindanao faces recurrent degradation from seismic activity, tropical cyclones, and storm surges. Through comprehensive non-destructive structural diagnostics and community evacuation routing, this program safeguards lives and critical educational assets.', '[{"title": "Structural Assessment", "description": "Conduct rebound hammer and ultrasonic pulse velocity tests on 5 evacuation facilities."}, {"title": "Retrofitting Blueprints", "description": "Deliver schematic structural improvement recommendations."}]', 'To enhance structural resilience and community disaster evacuation preparedness of public educational buildings in Barangay Mabua, Surigao City.', '["Evaluate masonry, reinforcement, and roofing vulnerabilities of 5 public structures.", "Establish localized evacuation route mappings with community DRRM personnel."]', '["5 complete structural engineering vulnerability assessments.", "1 evacuation roadmap handbook distributed to the barangay council."]', 'Addresses SDG 11 (Resilient Infrastructure) and SDG 13 (Climate Action).', '{"selected": [11, 13], "narrative": "Targets building safety and disaster risk mitigation."}', NULL, NULL, '[{"phase": "Field Testing & Structural Diagnostics", "outputs": "Testing data sheets", "target_month": "Week 1-3"}, {"phase": "Engineering Computation & Report Writing", "outputs": "Draft structural reports", "target_month": "Week 4-6"}, {"phase": "Stakeholders Turnover Workshop", "outputs": "Disaster blueprint handover", "target_month": "Week 7-8"}]', NULL, NULL, NULL, NULL, 12, 8, 'Maria Elena S. Villanueva', 'Faculty Proponent / Lead Engineer', '2026-10-19 13:20:33', 'concurred', 'Signed by Project Leader, Dean, and Extension Director. Currently on VP RIE desk for administrative endorsement.', NULL, '2026-10-24 05:20:33', '2026-11-03 01:35:46', NULL),
